import{_ as e,b as d,e as a,a8 as r}from"./chunks/framework.CNHV3T2x.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32","entity":"TCustomBitmap32","kind":"Class","declaration":"TCustomBitmap32 = class(TCustomMap)","inheritance":["TObject","TPersistent","TPlainInterfacedPersistent","TNotifiablePersistent","TThreadPersistent","TCustomMap","TCustomBitmap32"],"summary":"Abstract base class for 32-bit ARGB pixel bitmaps in Graphics32, defining backend surface management, sub-pixel sampling, drawing primitives, and resampling.","date":1787745975000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32/TCustomBitmap32/index.md","filePath":"api/GR32/TCustomBitmap32/index.md","lastUpdated":1787745975000,"timestamp":1787745975000,"datetime":"2026-08-26T12:06:15.000Z","contributors":[{"commits":1,"email":"anders@melander.dk","name":"Anders Melander","avatar":"https://gravatar.com/avatar/a6bff52a3ccbe999ab6406528ffe48f1","maintainer":false,"links":[]}]}'),o={name:"api/GR32/TCustomBitmap32/index.md"};function i(n,t,s,l,c,p){return d(),a("div",null,[...t[0]||(t[0]=[r('<h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p><code>TCustomBitmap32</code> is the primary 2D image data container in Graphics32. It extends <code>TCustomMap</code> with 32-bit ARGB pixel buffer management, hardware-abstracted rendering backends (<code>TCustomBackend</code>), spatial clipping (<code>ClipRect</code>), drawing modes (<code>DrawMode</code>, <code>CombineMode</code>), alpha blending (<code>MasterAlpha</code>), and customizable pixel resamplers (<code>TCustomResampler</code>).</p><p>Pixel elements are represented as 32-bit ARGB colors (<code>TColor32</code>). <code>TCustomBitmap32</code> provides extensive accessor methods for reading and writing pixels at integer, fixed-point (<code>TFixed</code>), or single-precision floating-point (<code>TFloat</code>) sub-pixel coordinates.</p><p>Derived Class: <a href="/api/GR32/TBitmap32/">TBitmap32</a></p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to &quot;Constructors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><a href="./Constructors/Create">Create</a></td><td>Initializes a new <code>TCustomBitmap32</code> instance with default or custom backend and dimensions.</td></tr></tbody></table><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="general-lifecycle" tabindex="-1">General &amp; Lifecycle <a class="header-anchor" href="#general-lifecycle" aria-label="Permalink to &quot;General &amp; Lifecycle&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><a href="./Methods/Assign">Assign</a></td><td>Copies pixel buffer and properties from another persistent object or bitmap.</td></tr><tr><td><a href="./Methods/BeginMeasuring">BeginMeasuring</a></td><td>Begins area change measurement and bounding box calculation.</td></tr><tr><td><a href="./Methods/BoundsRect">BoundsRect</a></td><td>Returns a <code>TRect</code> representing the bitmap dimensions <code>(0, 0, Width, Height)</code>.</td></tr><tr><td><a href="./Methods/Changed">Changed</a></td><td>Triggers update notifications for the entire bitmap or a specified sub-rectangle.</td></tr><tr><td><a href="./Methods/Clear">Clear</a></td><td>Clears the bitmap pixel buffer to zero (<code>clNone32</code>) or a specified <code>TColor32</code> fill color.</td></tr><tr><td><a href="./Methods/CopyMapTo">CopyMapTo</a></td><td>Copies raw map dimensions and pixel data to a target <code>TCustomBitmap32</code>.</td></tr><tr><td><a href="./Methods/Delete">Delete</a></td><td>Resets bitmap dimensions to zero and releases buffer memory.</td></tr><tr><td><a href="./Methods/Empty">Empty</a></td><td>Returns <code>True</code> if the bitmap has zero width or height.</td></tr><tr><td><a href="./Methods/EndMeasuring">EndMeasuring</a></td><td>Concludes area change measurement.</td></tr><tr><td><a href="./Methods/GetPlatformBackendClass">GetPlatformBackendClass</a></td><td>Class method returning the default platform backend class.</td></tr><tr><td><a href="./Methods/PropertyChanged">PropertyChanged</a></td><td>Notifies the bitmap and backend that a property has changed.</td></tr><tr><td><a href="./Methods/ReleaseBackend">ReleaseBackend</a></td><td>Detaches and returns the active backend instance without destroying it.</td></tr><tr><td><a href="./Methods/ResetClipRect">ResetClipRect</a></td><td>Resets <code>ClipRect</code> to cover the full bitmap bounds <code>(0, 0, Width, Height)</code>.</td></tr></tbody></table><h3 id="stream-file-i-o" tabindex="-1">Stream &amp; File I/O <a class="header-anchor" href="#stream-file-i-o" aria-label="Permalink to &quot;Stream &amp; File I/O&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><a href="./Methods/LoadFromFile">LoadFromFile</a></td><td>Loads bitmap data from a file on disk.</td></tr><tr><td><a href="./Methods/LoadFromResourceID">LoadFromResourceID</a></td><td>Loads bitmap data from an embedded resource by integer ID.</td></tr><tr><td><a href="./Methods/LoadFromResourceName">LoadFromResourceName</a></td><td>Loads bitmap data from an embedded resource by string name.</td></tr><tr><td><a href="./Methods/LoadFromStream">LoadFromStream</a></td><td>Loads bitmap data from a stream.</td></tr><tr><td><a href="./Methods/SaveToFile">SaveToFile</a></td><td>Saves bitmap data to a file on disk in BMP/DIB format.</td></tr><tr><td><a href="./Methods/SaveToStream">SaveToStream</a></td><td>Saves bitmap data to a stream in BMP/DIB format.</td></tr></tbody></table><h3 id="blitting-alpha-operations" tabindex="-1">Blitting &amp; Alpha Operations <a class="header-anchor" href="#blitting-alpha-operations" aria-label="Permalink to &quot;Blitting &amp; Alpha Operations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><a href="./Methods/Draw">Draw</a></td><td>Draws a source bitmap or sub-rectangle onto this bitmap.</td></tr><tr><td><a href="./Methods/DrawTo">DrawTo</a></td><td>Draws this bitmap or a sub-rectangle onto a target destination bitmap.</td></tr><tr><td><a href="./Methods/ResetAlpha">ResetAlpha</a></td><td>Resets alpha values of all pixels to <code>$FF</code> (opaque) or a specified alpha component.</td></tr><tr><td><a href="./Methods/SetPixelT">SetPixelT</a></td><td>Sets a pixel with alpha blending (<code>DrawMode</code> / <code>CombineMode</code>).</td></tr><tr><td><a href="./Methods/SetPixelTS">SetPixelTS</a></td><td>Sets a pixel with alpha blending and boundary clipping.</td></tr></tbody></table><h3 id="lines-drawing-primitives" tabindex="-1">Lines &amp; Drawing Primitives <a class="header-anchor" href="#lines-drawing-primitives" aria-label="Permalink to &quot;Lines &amp; Drawing Primitives&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><a href="./Methods/HorzLine">HorzLine</a></td><td>Draws an unclipped horizontal line at integer coordinates.</td></tr><tr><td><a href="./Methods/HorzLineS">HorzLineS</a></td><td>Draws a clipped horizontal line at integer coordinates.</td></tr><tr><td><a href="./Methods/HorzLineT">HorzLineT</a></td><td>Draws an unclipped blended horizontal line at integer coordinates.</td></tr><tr><td><a href="./Methods/HorzLineTS">HorzLineTS</a></td><td>Draws a clipped blended horizontal line at integer coordinates.</td></tr><tr><td><a href="./Methods/HorzLineTSP">HorzLineTSP</a></td><td>Draws a clipped blended horizontal line using current stipple pattern.</td></tr><tr><td><a href="./Methods/HorzLineX">HorzLineX</a></td><td>Draws an unclipped horizontal line at fixed-point coordinates.</td></tr><tr><td><a href="./Methods/HorzLineXS">HorzLineXS</a></td><td>Draws a clipped horizontal line at fixed-point coordinates.</td></tr><tr><td><a href="./Methods/VertLine">VertLine</a></td><td>Draws an unclipped vertical line at integer coordinates.</td></tr><tr><td><a href="./Methods/VertLineS">VertLineS</a></td><td>Draws a clipped vertical line at integer coordinates.</td></tr><tr><td><a href="./Methods/VertLineT">VertLineT</a></td><td>Draws an unclipped blended vertical line at integer coordinates.</td></tr><tr><td><a href="./Methods/VertLineTS">VertLineTS</a></td><td>Draws a clipped blended vertical line at integer coordinates.</td></tr><tr><td><a href="./Methods/VertLineTSP">VertLineTSP</a></td><td>Draws a clipped blended vertical line using current stipple pattern.</td></tr><tr><td><a href="./Methods/VertLineX">VertLineX</a></td><td>Draws an unclipped vertical line at fixed-point coordinates.</td></tr><tr><td><a href="./Methods/VertLineXS">VertLineXS</a></td><td>Draws a clipped vertical line at fixed-point coordinates.</td></tr><tr><td><a href="./Methods/Line">Line</a></td><td>Draws an unclipped arbitrary line segment at integer coordinates.</td></tr><tr><td><a href="./Methods/LineS">LineS</a></td><td>Draws a clipped arbitrary line segment at integer coordinates.</td></tr><tr><td><a href="./Methods/LineT">LineT</a></td><td>Draws an unclipped blended line segment at integer coordinates.</td></tr><tr><td><a href="./Methods/LineTS">LineTS</a></td><td>Draws a clipped blended line segment at integer coordinates.</td></tr><tr><td><a href="./Methods/LineA">LineA</a></td><td>Draws an unclipped anti-aliased line segment at integer coordinates.</td></tr><tr><td><a href="./Methods/LineAS">LineAS</a></td><td>Draws a clipped anti-aliased line segment at integer coordinates.</td></tr><tr><td><a href="./Methods/LineX">LineX</a></td><td>Draws an unclipped line segment at fixed-point coordinates.</td></tr><tr><td><a href="./Methods/LineF">LineF</a></td><td>Draws an unclipped line segment at floating-point coordinates.</td></tr><tr><td><a href="./Methods/LineXS">LineXS</a></td><td>Draws a clipped line segment at fixed-point coordinates.</td></tr><tr><td><a href="./Methods/LineFS">LineFS</a></td><td>Draws a clipped line segment at floating-point coordinates.</td></tr><tr><td><a href="./Methods/LineXP">LineXP</a></td><td>Draws an unclipped line segment using stipple pattern at fixed-point coordinates.</td></tr><tr><td><a href="./Methods/LineFP">LineFP</a></td><td>Draws an unclipped line segment using stipple pattern at floating-point coordinates.</td></tr><tr><td><a href="./Methods/LineXSP">LineXSP</a></td><td>Draws a clipped line segment using stipple pattern at fixed-point coordinates.</td></tr><tr><td><a href="./Methods/LineFSP">LineFSP</a></td><td>Draws a clipped line segment using stipple pattern at floating-point coordinates.</td></tr><tr><td><a href="./Methods/MoveTo">MoveTo</a></td><td>Sets current pen position for subsequent <code>LineTo</code> drawing operations.</td></tr><tr><td><a href="./Methods/MoveToX">MoveToX</a></td><td>Sets current fixed-point pen position for subsequent <code>LineTo</code> drawing operations.</td></tr><tr><td><a href="./Methods/MoveToF">MoveToF</a></td><td>Sets current floating-point pen position for subsequent <code>LineTo</code> drawing operations.</td></tr><tr><td><a href="./Methods/LineToS">LineToS</a></td><td>Draws a clipped line from current pen position to target integer point.</td></tr><tr><td><a href="./Methods/LineToTS">LineToTS</a></td><td>Draws a clipped blended line from current pen position to target integer point.</td></tr><tr><td><a href="./Methods/LineToAS">LineToAS</a></td><td>Draws a clipped anti-aliased line from current pen position to target integer point.</td></tr><tr><td><a href="./Methods/LineToXS">LineToXS</a></td><td>Draws a clipped line from current fixed-point pen position to target point.</td></tr><tr><td><a href="./Methods/LineToFS">LineToFS</a></td><td>Draws a clipped line from current floating-point pen position to target point.</td></tr><tr><td><a href="./Methods/LineToXSP">LineToXSP</a></td><td>Draws a clipped stippled line from current fixed-point pen position to target point.</td></tr><tr><td><a href="./Methods/LineToFSP">LineToFSP</a></td><td>Draws a clipped stippled line from current floating-point pen position to target point.</td></tr></tbody></table><h3 id="rectangles-shapes" tabindex="-1">Rectangles &amp; Shapes <a class="header-anchor" href="#rectangles-shapes" aria-label="Permalink to &quot;Rectangles &amp; Shapes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><a href="./Methods/FillRect">FillRect</a></td><td>Fills an unclipped rectangular region with a specified color.</td></tr><tr><td><a href="./Methods/FillRectS">FillRectS</a></td><td>Fills a clipped rectangular region with a specified color.</td></tr><tr><td><a href="./Methods/FillRectT">FillRectT</a></td><td>Fills an unclipped rectangular region using alpha blending.</td></tr><tr><td><a href="./Methods/FillRectTS">FillRectTS</a></td><td>Fills a clipped rectangular region using alpha blending.</td></tr><tr><td><a href="./Methods/FrameRectS">FrameRectS</a></td><td>Draws a 1-pixel clipped rectangular frame.</td></tr><tr><td><a href="./Methods/FrameRectTS">FrameRectTS</a></td><td>Draws a 1-pixel clipped alpha-blended rectangular frame.</td></tr><tr><td><a href="./Methods/FrameRectTSP">FrameRectTSP</a></td><td>Draws a 1-pixel clipped stippled rectangular frame.</td></tr><tr><td><a href="./Methods/RaiseRectTS">RaiseRectTS</a></td><td>Draws a 3D bevelled button/panel edge.</td></tr></tbody></table><h3 id="transformations" tabindex="-1">Transformations <a class="header-anchor" href="#transformations" aria-label="Permalink to &quot;Transformations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><a href="./Methods/Roll">Roll</a></td><td>Scrolls/shifts pixel contents horizontally and vertically with optional background fill.</td></tr><tr><td><a href="./Methods/FlipHorz">FlipHorz</a></td><td>Flips pixel contents horizontally (left to right).</td></tr><tr><td><a href="./Methods/FlipVert">FlipVert</a></td><td>Flips pixel contents vertically (top to bottom).</td></tr><tr><td><a href="./Methods/Rotate90">Rotate90</a></td><td>Rotates bitmap contents 90 degrees clockwise.</td></tr><tr><td><a href="./Methods/Rotate180">Rotate180</a></td><td>Rotates bitmap contents 180 degrees.</td></tr><tr><td><a href="./Methods/Rotate270">Rotate270</a></td><td>Rotates bitmap contents 270 degrees clockwise (90 degrees counter-clockwise).</td></tr></tbody></table><h3 id="stipple-methods" tabindex="-1">Stipple Methods <a class="header-anchor" href="#stipple-methods" aria-label="Permalink to &quot;Stipple Methods&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><a href="./Methods/SetStipple">SetStipple</a></td><td>Sets custom stipple color array pattern.</td></tr><tr><td><a href="./Methods/AdvanceStippleCounter">AdvanceStippleCounter</a></td><td>Advances stipple counter position by specified distance in pixels.</td></tr><tr><td><a href="./Methods/GetStippleColor">GetStippleColor</a></td><td>Evaluates and returns current stipple color.</td></tr></tbody></table><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="pixel-accessors" tabindex="-1">Pixel Accessors <a class="header-anchor" href="#pixel-accessors" aria-label="Permalink to &quot;Pixel Accessors&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Scope</th><th>Description</th></tr></thead><tbody><tr><td><a href="./Properties/Pixel">Pixel</a></td><td><code>TColor32</code></td><td>Public</td><td>Default indexed accessor for reading and writing pixels at integer coordinates <code>[X, Y]</code>.</td></tr><tr><td><a href="./Properties/PixelS">PixelS</a></td><td><code>TColor32</code></td><td>Public</td><td>Boundary-clipped pixel accessor at integer coordinates <code>[X, Y]</code>.</td></tr><tr><td><a href="./Properties/PixelW">PixelW</a></td><td><code>TColor32</code></td><td>Public</td><td>Wrapped pixel accessor at integer coordinates <code>[X, Y]</code>.</td></tr><tr><td><a href="./Properties/PixelX">PixelX</a></td><td><code>TColor32</code></td><td>Public</td><td>Pixel accessor at fixed-point coordinates <code>[X, Y]</code>.</td></tr><tr><td><a href="./Properties/PixelXS">PixelXS</a></td><td><code>TColor32</code></td><td>Public</td><td>Boundary-clipped pixel accessor at fixed-point coordinates <code>[X, Y]</code>.</td></tr><tr><td><a href="./Properties/PixelXW">PixelXW</a></td><td><code>TColor32</code></td><td>Public</td><td>Wrapped pixel accessor at fixed-point coordinates <code>[X, Y]</code>.</td></tr><tr><td><a href="./Properties/PixelF">PixelF</a></td><td><code>TColor32</code></td><td>Public</td><td>Sub-pixel accessor at floating-point coordinates <code>[X, Y]</code>.</td></tr><tr><td><a href="./Properties/PixelFS">PixelFS</a></td><td><code>TColor32</code></td><td>Public</td><td>Boundary-clipped sub-pixel accessor at floating-point coordinates <code>[X, Y]</code>.</td></tr><tr><td><a href="./Properties/PixelFW">PixelFW</a></td><td><code>TColor32</code></td><td>Public</td><td>Wrapped sub-pixel accessor at floating-point coordinates <code>[X, Y]</code>.</td></tr><tr><td><a href="./Properties/PixelFR">PixelFR</a></td><td><code>TColor32</code></td><td>Public</td><td>Read-only resampled sub-pixel accessor at floating-point coordinates <code>[X, Y]</code>.</td></tr><tr><td><a href="./Properties/PixelXR">PixelXR</a></td><td><code>TColor32</code></td><td>Public</td><td>Read-only resampled sub-pixel accessor at fixed-point coordinates <code>[X, Y]</code>.</td></tr></tbody></table><h3 id="pen-stipple-properties" tabindex="-1">Pen &amp; Stipple Properties <a class="header-anchor" href="#pen-stipple-properties" aria-label="Permalink to &quot;Pen &amp; Stipple Properties&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Scope</th><th>Description</th></tr></thead><tbody><tr><td><a href="./Properties/PenColor">PenColor</a></td><td><code>TColor32</code></td><td>Public</td><td>Color used for pen drawing operations (<code>MoveTo</code>, <code>LineTo</code>).</td></tr><tr><td><a href="./Properties/PenPos">PenPos</a></td><td><code>TPoint</code></td><td>Public</td><td>Current integer pen coordinate position.</td></tr><tr><td><a href="./Properties/PenPosF">PenPosF</a></td><td><code>TFixedPoint</code></td><td>Public</td><td>Current fixed-point pen coordinate position.</td></tr><tr><td><a href="./Properties/StippleCounter">StippleCounter</a></td><td><code>Single</code></td><td>Public</td><td>Current phase position index along stipple pattern array.</td></tr><tr><td><a href="./Properties/StippleStep">StippleStep</a></td><td><code>Single</code></td><td>Public</td><td>Step distance increment for stipple pattern evaluation.</td></tr></tbody></table><h3 id="buffer-backend-properties" tabindex="-1">Buffer &amp; Backend Properties <a class="header-anchor" href="#buffer-backend-properties" aria-label="Permalink to &quot;Buffer &amp; Backend Properties&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Scope</th><th>Description</th></tr></thead><tbody><tr><td><a href="./Properties/Backend">Backend</a></td><td><code>TCustomBackend</code></td><td>Public</td><td>Active rendering surface backend instance.</td></tr><tr><td><a href="./Properties/Bits">Bits</a></td><td><code>PColor32Array</code></td><td>Public</td><td>Pointer to contiguous raw 32-bit ARGB pixel memory buffer.</td></tr><tr><td><a href="./Properties/ClipRect">ClipRect</a></td><td><code>TRect</code></td><td>Public</td><td>Clipping rectangle restricting pixel modifications.</td></tr><tr><td><a href="./Properties/Clipping">Clipping</a></td><td><code>Boolean</code></td><td>Public</td><td>Read-only flag indicating if <code>ClipRect</code> active region is smaller than full bitmap dimensions.</td></tr><tr><td><a href="./Properties/MeasuringMode">MeasuringMode</a></td><td><code>Boolean</code></td><td>Public</td><td>Indicates whether area change measurement is active.</td></tr><tr><td><a href="./Properties/PixelPtr">PixelPtr</a></td><td><code>PColor32</code></td><td>Public</td><td>Pointer to specific pixel at integer coordinates <code>[X, Y]</code>.</td></tr><tr><td><a href="./Properties/ScanLine">ScanLine</a></td><td><code>PColor32Array</code></td><td>Public</td><td>Pointer to starting pixel memory location for scanline row <code>[Y]</code>.</td></tr></tbody></table><h3 id="drawing-modes-resampling" tabindex="-1">Drawing Modes &amp; Resampling <a class="header-anchor" href="#drawing-modes-resampling" aria-label="Permalink to &quot;Drawing Modes &amp; Resampling&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Scope</th><th>Description</th></tr></thead><tbody><tr><td><a href="./Properties/CombineMode">CombineMode</a></td><td><code>TCombineMode</code></td><td>Published</td><td>Pixel combination mode (<code>cmBlend</code>, <code>cmMerge</code>, <code>cmModulo</code>, etc.).</td></tr><tr><td><a href="./Properties/DrawMode">DrawMode</a></td><td><code>TDrawMode</code></td><td>Published</td><td>Draw mode (<code>dmOpaque</code>, <code>dmBlend</code>, <code>dmCustom</code>).</td></tr><tr><td><a href="./Properties/MasterAlpha">MasterAlpha</a></td><td><code>Cardinal</code></td><td>Published</td><td>Global alpha scaling factor (<code>0</code> to <code>255</code>) applied to draw operations.</td></tr><tr><td><a href="./Properties/OuterColor">OuterColor</a></td><td><code>TColor32</code></td><td>Published</td><td>Color returned when sampling outside bitmap bounds in safe/transparent mode.</td></tr><tr><td><a href="./Properties/Resampler">Resampler</a></td><td><code>TCustomResampler</code></td><td>Published</td><td>Active resampler engine instance for sub-pixel stretching and sampling.</td></tr><tr><td><a href="./Properties/ResamplerClassName">ResamplerClassName</a></td><td><code>string</code></td><td>Published</td><td>Class name string of current resampler engine.</td></tr><tr><td><a href="./Properties/WrapMode">WrapMode</a></td><td><code>TWrapMode</code></td><td>Published</td><td>Boundary wrapping mode (<code>wmClamp</code>, <code>wmRepeat</code>, <code>wmMirror</code>).</td></tr></tbody></table><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><a href="./Events/OnAreaChanged">OnAreaChanged</a></td><td><code>TAreaChangedEvent</code></td><td>Fired when a specific sub-rectangle region of pixel memory is updated.</td></tr><tr><td><a href="./Events/OnPixelCombine">OnPixelCombine</a></td><td><code>TPixelCombineEvent</code></td><td>Custom pixel combination callback event when <code>DrawMode = dmCustom</code>.</td></tr></tbody></table>',32)])])}const f=e(o,[["render",i]]);export{m as __pageData,f as default};
